function parseHours(totalHours, isTotal)
{
    if(totalHours == 0)
    {
        return "-";
    }
    else if (totalHours == null)
    {
        return isTotal? "Geen data ontvangen" : "-";
    }

    const totalMinutes = Math.round(totalHours * 60);
    const runhours = Math.floor(totalMinutes / 60);
    const runminutes = totalMinutes % 60;

    if(runminutes == 0) return `${runhours} uur`;
    if(runhours == 0) return `${runminutes} minuten`;

    return `${runhours} uur, ${runminutes} minuten`;
}

