function weightedAverage(dailyAvg, weeklyAvg, monthlyAvg) 
{
    const weights = { daily: 0.5, weekly: 0.3, monthly: 0.2 };
    return (dailyAvg * weights.daily) +
           (weeklyAvg / 7 * weights.weekly) +   // convert weekly to per-day
           (monthlyAvg / 30 * weights.monthly); // convert monthly to per-day
}

function predictDate(currentHours, dailyAvg, weeklyAvg, monthlyAvg) 
{
